function renderBatchHistory(jobs){$('batchHistory').innerHTML=jobs.length?`<div class="batch-history-title">Recent batch jobs</div>`+jobs.map(j=>`<div class="batch-job"><span><b>${new Date(j.timestamp).toLocaleString()}</b><small>${j.rows} rows · ${j.labeled} labeled</small></span><span>${j.high_risk} high risk</span><span>${fmt(j.avg_probability*100,1)}% average risk</span><a class="text-link" href="/api/export/batch/${j.id}.csv">Download results</a></div>`).join(''):'<div class="empty">No batch jobs uploaded yet.</div>'}
function renderMonitorSettings(settings){$('monitorEnabled').checked=!!settings.monitoring_enabled;$('monitorShift').checked=!!settings.monitoring_simulate_drift;$('monitorInterval').value=String(settings.monitoring_interval_seconds||60);$('monitorStatus').textContent=settings.monitoring_enabled?'RUNNING':'STOPPED';$('monitorDetails').textContent=settings.monitoring_enabled?`Scored ${settings.monitoring_generated||0} telemetry events. Last run: ${settings.monitoring_last_run?new Date(settings.monitoring_last_run).toLocaleString():'waiting'}.`:'Disabled. Scheduled scoring will start only after you enable it.'}
async function scanDrift(){try{const s=await api('drift/snapshot',{});await refresh();toast(`Drift scan saved. ${s.features.filter(f=>f.status==='HIGH').length} feature(s) above PSI 0.25.`)}catch(e){showError(e)}}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted&&ch==='"'&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()!==''))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(x=>x.trim()!==''))rows.push(row);if(quoted)throw new Error('CSV has an unclosed quoted field.');if(rows.length<2)throw new Error('CSV must contain a header and at least one data row.');const headers=rows[0].map(x=>x.trim().replace(/^\uFEFF/,'')),required=['latency_ms','error_rate','cpu_pct','memory_pct','drift_score','request_rate'];const missing=required.filter(k=>!headers.includes(k));if(missing.length)throw new Error(`Missing required columns: ${missing.join(', ')}`);return rows.slice(1).map((r,i)=>{const out={};for(const k of required){const j=headers.indexOf(k),v=(r[j]||'').trim();if(!v)throw new Error(`Row ${i+2}: ${k} is empty.`);out[k]=Number(v);if(!Number.isFinite(out[k]))throw new Error(`Row ${i+2}: ${k} must be numeric.`)}const labelIndex=headers.indexOf('failure');if(labelIndex>=0&&(r[labelIndex]||'').trim()!==''){const v=r[labelIndex].trim().toLowerCase();if(!['true','false','1','0','yes','no'].includes(v))throw new Error(`Row ${i+2}: failure must be true/false or 1/0.`);out.failure=['true','1','yes'].includes(v)}return out})}
async function uploadBatch(){try{const file=$('batchFile').files[0];if(!file)throw new Error('Choose a CSV file first.');$('batchMessage').textContent='Reading and scoring CSV…';const rows=parseCsv(await file.text()),result=await api('batch/score',{rows}),job=result.job;$('batchMessage').textContent=`Scored ${job.rows} rows; ${job.labeled} observed outcome(s) recorded.`;$('batchResult').innerHTML=`<b>Batch complete</b><span>${job.high_risk} high-risk rows</span><span>${fmt(job.avg_probability*100,1)}% average predicted risk</span>`;$('batchDownload').href=`/api/export/batch/${job.id}.csv`;$('batchDownload').classList.remove('hidden');await refresh();toast('CSV batch scored and saved.')}catch(e){$('batchMessage').textContent=e.message;showError(e)}}
async function saveMonitorSettings(){try{const result=await api('monitoring/config',{enabled:$('monitorEnabled').checked,interval_seconds:Number($('monitorInterval').value),simulate_drift:$('monitorShift').checked});renderMonitorSettings(result.monitoring);toast(result.monitoring.monitoring_enabled?'Scheduled monitor enabled.':'Scheduled monitor stopped.')}catch(e){showError(e)}}
async function refresh(){try{const d=await api('metrics?range='+encodeURIComponent($('overviewRange')?.value||'all'));currentMetrics=d;renderOverview(d);renderPredictions(d);renderDrift(d.feature_means);renderAlerts(d.alerts);renderCalibration(d.calibration);renderDriftHistory(d.drift_snapshots);renderBatchHistory(d.batch_jobs);renderMonitorSettings(d.settings);renderAnomalies(d);renderQuality(d);renderThresholdComparison(d.threshold_comparison);drawExtraCharts(d);$('lastUpdated').textContent=`Updated ${new Date().toLocaleTimeString()}`;$('serviceState').innerHTML='<i></i> SERVICE CONNECTED';$('serviceState').classList.remove('disconnected');if(location.hash==='#agent')renderAgentChoices();if(!$('lowThreshold').value){$('lowThreshold').value=d.settings.low;$('highThreshold').value=d.settings.high}}catch(e){$('serviceState').innerHTML='<i></i> SERVICE UNAVAILABLE';$('serviceState').classList.add('disconnected');showError(e)}}
async function score(){try{const input=Object.fromEntries(Object.keys(defaults).map(k=>[k,Number($('f_'+k).value)]));if(Object.values(input).some(v=>!Number.isFinite(v)))throw new Error('Enter a valid number for every telemetry feature.');const r=await api('predict',input),box=$('result');box.className='result '+r.risk.toLowerCase();box.innerHTML=`<b>${r.risk} RISK</b> · Failure probability ${fmt(r.probability*100)}% <span>(next hour estimate)</span><button class="tiny ai-review" onclick="triagePrediction('${r.id}')">✦ Explain with triage agent</button>`;await refresh()}catch(e){showError(e)}}
function renderAgentChoices(){const select=$('agentPrediction');if(!select||!currentMetrics)return;const previous=select.value,rows=currentMetrics.recent||[];select.innerHTML=rows.length?rows.map(p=>`<option value="${p.id}">${new Date(p.timestamp).toLocaleString()} · ${p.risk} · ${fmt(p.probability*100)}%</option>`).join(''):'<option value="">No predictions available</option>';if(rows.some(p=>p.id===previous))select.value=previous;$('agentToolCount').textContent='4 TOOLS'}
async function runAgent(id){try{renderAgentChoices();const predictionId=id||$('agentPrediction').value;if(!predictionId)throw new Error('Create a prediction before running triage.');$('agentEmpty').classList.add('hidden');$('agentReport').classList.remove('hidden');$('agentSummary').innerHTML='<div class="agent-loading">Agent is gathering prediction, model, drift, and alert evidence…</div>';const report=await api('agent/triage',{prediction_id:predictionId});renderAgentReport(report);$('agentPrediction').value=predictionId}catch(e){showError(e)}}
function renderAgentReport(r){$('agentSummary').innerHTML=`<div class="agent-summary-top"><span class="risk-tag ${r.prediction.risk.toLowerCase()}">${r.prediction.risk} RISK</span><span class="agent-probability">${fmt(r.prediction.probability*100)}%</span><span class="model-chip">MODEL <b>v${r.prediction.model_version}</b></span><span class="agent-time">${new Date(r.created_at).toLocaleString()}</span></div><p>${r.summary}</p><small>SHAP output: log-odds ? independent-feature background assumption. ${r.guardrail}</small>`;const max=Math.max(...r.drivers.map(x=>Math.abs(x.contribution)),.01);$('agentDrivers').innerHTML=r.drivers.map(x=>`<div class="agent-driver"><div class="driver-copy"><b>${x.label}</b><span>${fmt(x.value,3)} live · ${fmt(x.baseline,3)} train</span></div><div class="driver-meter"><i class="${x.contribution<0?'protective':''}" style="width:${Math.abs(x.contribution)/max*100}%"></i></div><small class="${x.contribution<0?'protective-text':''}">${x.contribution>=0?'+':''}SHAP ${x.shap_value>=0?'+':''}${fmt(x.shap_value??x.contribution,3)} log-odds</small></div>`).join('');$('agentPlan').innerHTML=r.plan.map((x,i)=>`<div class="plan-step"><span class="plan-number">${String(i+1).padStart(2,'0')}</span><div><b>${x.title}</b><p>${x.detail}</p></div><span class="plan-priority ${x.priority.toLowerCase().replaceAll(' ','-')}">${x.priority}</span></div>`).join('');$('agentTraceCount').textContent=`${r.trace.length} STEPS`;$('agentTrace').innerHTML=r.trace.map((x,i)=>`<div class="trace-step"><span class="trace-number">${i+1}</span><div><b>${x.tool.replaceAll('_',' ')}</b><small>${x.purpose}</small></div><span class="trace-result">${x.result}</span></div>`).join('')}
async function triagePrediction(id){location.hash='#agent';renderAgentChoices();if(id)$('agentPrediction').value=id;await runAgent(id)}
async function feedback(id,failure){try{await api('feedback',{id,failure});await refresh();toast('Observed outcome saved. Model monitoring metrics updated.')}catch(e){showError(e)}}
async function acknowledge(id){try{await api(`alerts/${encodeURIComponent(id)}/ack`,{});await refresh();toast('Alert acknowledged.')}catch(e){showError(e)}}
function draftIncident(id,key,value){incidentDrafts[id]={...(incidentDrafts[id]||{}),[key]:value}}
async function saveIncident(id){try{const d=incidentDrafts[id]||{},result=await api(`incidents/${encodeURIComponent(id)}/update`,{owner:d.owner??$(`owner_${id}`).value,notes:d.notes??$(`notes_${id}`).value,root_cause:d.root_cause??$(`root_${id}`).value,resolution:d.resolution??$(`resolution_${id}`).value,status:d.status??$(`status_${id}`).value});delete incidentDrafts[id];await refresh();toast(`Incident saved as ${result.incident.status}.`)}catch(e){showError(e)}}
async function simulate(){try{const r=await api('simulate?count=120',{});toast(`Generated ${r.generated} shifted events. Latency baseline ${fmt(r.latency_baseline,0)} ms; observed ${fmt(r.latency_observed,0)} ms.`);await refresh()}catch(e){showError(e)}}
async function resetData(){try{await api('reset',{});$('result').className='result hidden';await refresh();toast('Demo monitoring data cleared. Risk threshold settings were kept.')}catch(e){showError(e)}}
async function saveSettings(){try{const low=Number($('lowThreshold').value),high=Number($('highThreshold').value);const r=await api('settings',{low,high});$('settingsMessage').textContent=`Saved: LOW < ${fmt(r.settings.low*100,0)}%, MEDIUM < ${fmt(r.settings.high*100,0)}%, otherwise HIGH.`;await refresh();toast('Risk thresholds updated.')}catch(e){$('settingsMessage').textContent=e.message;$('settingsMessage').style.color='#c3423e'}}
async function checkHealth(){try{const h=await api('health');$('serviceDetails').innerHTML=`<div class="detail-row"><span>Status</span><b style="color:#168553">${h.status.toUpperCase()}</b></div><div class="detail-row"><span>Service</span><b>${h.service}</b></div><div class="detail-row"><span>Model</span><b>v${h.model_version}</b></div><div class="detail-row"><span>Checked</span><b>${new Date().toLocaleTimeString()}</b></div>`;toast('Prediction service is healthy.')}catch(e){$('serviceDetails').innerHTML=`<div class="detail-row"><span>Status</span><b style="color:#c3423e">UNAVAILABLE</b></div>`;showError(e)}}
async function retrain(){const button=document.querySelector('.model-actions .primary');button.disabled=true;button.textContent='Training model...';try{const result=await api('retrain',{});const m=await api('model');renderModel(m);renderRegistry(m.registry||[]);await refresh();toast(`Model v${result.version} trained, evaluated, and promoted.`)}catch(e){showError(e)}finally{button.disabled=false;button.innerHTML='⟳ &nbsp; Retrain model'}}
async function trainFeedbackCandidate(){try{const result=await api('retrain/feedback',{}),m=await api('model');renderModel(m);renderRegistry(m.registry||[]);toast(`Candidate v${result.version} trained on ${result.labeled_samples} reviewed outcomes. Compare before promoting.`)}catch(e){showError(e)}}
async function promoteModel(version){try{const result=await api(`models/${encodeURIComponent(version)}/promote`,{}),m=await api('model');renderModel(m);renderRegistry(m.registry||[]);await refresh();toast(`Model v${result.version} is now active.`)}catch(e){showError(e)}}
async function rollbackModel(version){try{const result=await api('models/rollback',{version}),m=await api('model');renderModel(m);renderRegistry(m.registry||[]);await refresh();toast(`Rolled back to model v${result.version}.`)}catch(e){showError(e)}}
window.addEventListener('hashchange',route);window.addEventListener('resize',()=>{if(currentMetrics)renderChart(currentMetrics.recent)});setupExtraPages();renderForm();route();Promise.all([refresh(),api('model').then(m=>{renderModel(m);renderRegistry(m.registry||[])}).catch(showError)]);setInterval(refresh,10000);
